WM=[("enormous","very, very big"),("tiny","very small"),("ancient","very old"),("delicious","tasting very good"),("fragile","easy to break"),("brave","not afraid of danger"),("generous","happy to share and give"),("curious","wanting to learn or know more"),("exhausted","very, very tired"),("peaceful","calm and quiet"),("rapid","very fast"),("hungry","wanting food"),("thirsty","wanting a drink"),("gigantic","extremely large"),("timid","shy and easily scared"),("silent","making no sound"),("lonely","feeling sad about being alone"),("honest","telling the truth"),("patient","able to wait calmly"),("fierce","strong and a little scary"),("polite","having good manners"),("cautious","careful to avoid danger"),("adventure","an exciting trip or experience"),("journey","a trip from one place to another"),("harvest","gathering crops when they are ready"),("shelter","a place that keeps you safe from weather"),("fossil","the old remains of a plant or animal in rock"),("volcano","a mountain that can erupt with hot lava"),("telescope","a tool for seeing faraway things like stars"),("microscope","a tool for seeing very tiny things"),("thermometer","a tool that measures temperature"),("compass","a tool that shows which way is north"),("map","a drawing that shows where places are"),("dictionary","a book that tells what words mean"),("diary","a book where you write about your days"),("librarian","a person who works in a library"),("architect","a person who designs buildings"),("pilot","a person who flies an airplane"),("farmer","a person who grows food and raises animals"),("astronaut","a person who travels into space")]
HWM=[("gentle","soft and kind"),("scientist","a person who studies how things work"),("fortunate","lucky")]
g("word meanings, next level","Good: a short, true definition.",[(f"What does '{a}' mean?",f"'{cap(a)}' means {b}.",b.split()[-1]) for a,b in WM])
h([(f"What does '{a}' mean?",f"'{cap(a)}' means {b}.",b.split()[-1]) for a,b in HWM])
# ---- grammar fixes
GF=[("Fix this: 'Me and him goes to school.'","He and I go to school.","he and i go"),("Fix this: 'She don't like peas.'","She doesn't like peas.","doesn't"),("Fix this: 'They was happy.'","They were happy.","were"),("Fix this: 'I seen a bird.'","I saw a bird.","saw"),("Fix this: 'He runned fast.'","He ran fast.","ran"),("Fix this: 'We has a dog.'","We have a dog.","have"),("Fix this: 'Him is tall.'","He is tall.","he is"),("Fix this: 'I have two cat.'","I have two cats.","cats"),("Fix this: 'There is three birds.'","There are three birds.","are"),("Fix this: 'She sing very good.'","She sings very well.","well"),("Fix this: 'Me like cake.'","I like cake.","i like"),("Fix this: 'The childs played.'","The children played.","children"),("Fix this: 'He goed home.'","He went home.","went"),("Fix this: 'A apple is red.'","An apple is red.","an apple"),("Fix this: 'i am happy.'","I am happy.","I am")]
g("fix the sentence","Good: fixes the grammar and keeps the meaning.",GF)
h([("Fix this: 'He don't know.'","He doesn't know.","doesn't"),("Fix this: 'We was late.'","We were late.","were"),("Fix this: 'She have a book.'","She has a book.","has")])
# ---- reading and inference
RD=[("Tia packed her swimsuit and a towel. Where is she going?","She is probably going swimming.","swim|pool|beach"),("The sky turned dark and the wind grew loud. What might happen next?","It might start to storm.","storm|rain|thunder"),("Sam yawned and rubbed his eyes at nine at night. How does he feel?","He feels sleepy.","sleep|tired"),("Ruth smiled and clapped when she saw the cake. How does she feel?","She feels happy.","happy|excited|glad"),("The ice cream was left in the sun. What happened to it?","It melted.","melt"),("Leo studied hard for the test. What will probably happen?","He will probably do well.","well|good|pass"),("The plant was never given water. What will happen to it?","It will wilt or die.","wilt|die|dry"),("Mia put on her coat, hat, and gloves. What is the weather?","It is probably cold.","cold|chilly|snow|winter"),("The dog wagged its tail and ran to the door when the key turned. How does it feel?","It feels happy to see its person.","happy|excited|glad"),("Ana held the umbrella high as the drops fell. What is the weather?","It is raining.","rain"),("Ben's lamp went out and the room went dark. What could he do?","He could change the bulb or find another light.","bulb|light|flashlight|candle"),("A girl found a lost puppy and took it to its owner. Was that kind?","Yes, that was kind and helpful.","yes|kind")]
g("reading and clues","Good: uses the clue in the sentence to answer.",RD)
h([("Jon grabbed his bat and glove and ran to the field. What will he do?","He will probably play baseball.","baseball|play|game"),("The baby cried and rubbed her tummy. What does she need?","She is probably hungry.","hungry|food|milk")])
